CREATE TABLE IF NOT EXISTS V1_META(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS V1_SESSIONS(token_hash TEXT PRIMARY KEY,account_id INTEGER NOT NULL REFERENCES ACCOUNTS(account_id),role_id INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS V1_STOCK(stock_key TEXT PRIMARY KEY,available_units INTEGER NOT NULL CHECK(available_units>=0));
INSERT OR IGNORE INTO V1_STOCK VALUES('H1',4),('H2',4),('ARM_1',8),('ARM_2',8),('ARM_3',8),('BODY',8);
CREATE TABLE IF NOT EXISTS V1_ORDERS(
 order_id TEXT PRIMARY KEY,internal_number INTEGER NOT NULL UNIQUE,company TEXT NOT NULL,phone TEXT NOT NULL,address TEXT NOT NULL,
 spec TEXT NOT NULL,payment_method TEXT NOT NULL,target_station INTEGER NOT NULL CHECK(target_station IN(3,4,5)),dispatch_station INTEGER,
 factory_status TEXT NOT NULL DEFAULT 'PENDING',approval_seq INTEGER UNIQUE,cycle_id TEXT,pallet_id TEXT,
 progress TEXT NOT NULL DEFAULT 'RECEIVED',outcome TEXT NOT NULL DEFAULT 'OPEN',stock_restored INTEGER NOT NULL DEFAULT 0,
 created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS V1_REQUESTS(scope TEXT NOT NULL,request_id TEXT NOT NULL,payload_hash TEXT NOT NULL,response TEXT NOT NULL,status INTEGER NOT NULL,PRIMARY KEY(scope,request_id));
CREATE TABLE IF NOT EXISTS V1_PALLETS(pallet_id TEXT PRIMARY KEY,cycle_id TEXT,stage TEXT NOT NULL DEFAULT 'READY',updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS V1_PLANT(id INTEGER PRIMARY KEY CHECK(id=1),state TEXT NOT NULL DEFAULT 'NOT_READY',stage TEXT NOT NULL DEFAULT 'READY',cycle_id TEXT,auto_enabled INTEGER NOT NULL DEFAULT 0,action_request TEXT,pause_ids TEXT NOT NULL DEFAULT '{}',updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS V1_CYCLES(cycle_id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES V1_ORDERS(order_id),pallet_id TEXT,stage TEXT NOT NULL,closed INTEGER NOT NULL DEFAULT 0,qr TEXT,qr_due REAL,inspection_id TEXT,pending_event TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,flow_version TEXT NOT NULL DEFAULT '0.2.0');
CREATE UNIQUE INDEX IF NOT EXISTS V1_ONE_CYCLE ON V1_CYCLES(closed) WHERE closed=0;
CREATE TABLE IF NOT EXISTS V1_DEVICES(device_id TEXT PRIMARY KEY,boot_id TEXT NOT NULL,status TEXT NOT NULL,last_seen REAL NOT NULL DEFAULT 0,last_seq INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS V1_COMMANDS(command_id TEXT PRIMARY KEY,device_id TEXT NOT NULL,cycle_id TEXT,action TEXT NOT NULL,params TEXT NOT NULL,expected_boot_id TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'ACCEPTED',attempted INTEGER NOT NULL DEFAULT 0,result_event_id TEXT,error TEXT,ticket_id TEXT,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS V1_EVENTS(event_id TEXT PRIMARY KEY,device_id TEXT NOT NULL,boot_id TEXT NOT NULL,event_seq INTEGER NOT NULL,body TEXT NOT NULL,disposition TEXT NOT NULL,processed INTEGER NOT NULL DEFAULT 0,UNIQUE(device_id,boot_id,event_seq));
CREATE TABLE IF NOT EXISTS V1_HISTORY(record_id TEXT PRIMARY KEY,order_id TEXT NOT NULL,cycle_id TEXT,command_id TEXT,inspection_id TEXT,recorded_at TEXT NOT NULL,stage TEXT NOT NULL,kind TEXT NOT NULL,message TEXT NOT NULL,extra TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS V1_TICKETS(request_id TEXT PRIMARY KEY,kind TEXT NOT NULL,state TEXT NOT NULL,cycle_id TEXT,read_id TEXT);
CREATE TABLE IF NOT EXISTS V1_AUDIT(audit_id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,body TEXT NOT NULL,recorded_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS V1_VISION_JOBS(job_id TEXT PRIMARY KEY,cycle_id TEXT NOT NULL,action TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'PENDING');
CREATE TABLE IF NOT EXISTS V1_RATE_LIMIT(key TEXT PRIMARY KEY,window INTEGER NOT NULL,hits INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS V1_CONTROLLER_LEASE(id INTEGER PRIMARY KEY CHECK(id=1),instance_id TEXT NOT NULL,heartbeat REAL NOT NULL);
CREATE TABLE IF NOT EXISTS V1_ARM_CHECKPOINTS(
    checkpoint_id TEXT PRIMARY KEY REFERENCES V1_EVENTS(event_id),
    command_id TEXT NOT NULL REFERENCES V1_COMMANDS(command_id),
    part_index INTEGER NOT NULL, part TEXT NOT NULL, after_frame REAL NOT NULL,
    state TEXT NOT NULL DEFAULT 'WAIT_FRAME', body TEXT, note TEXT);
CREATE INDEX IF NOT EXISTS V1_ARM_CHECKPOINT_COMMAND ON V1_ARM_CHECKPOINTS(command_id,part_index);
